## Fluxo de CRUD (exemplo)

```ts
// backend/src/routes/todo.ts
import { Router } from 'express';
import { prisma } from '../prisma';
import { validateTodo } from '../middlewares/validate';

const router = Router();

router.get('/', async (req, res) => {
  const todos = await prisma.todo.findMany({ where: { userId: req.user.id } });
  res.json(todos);
});

router.post('/', validateTodo, async (req, res) => {
  const todo = await prisma.todo.create({
    data: { ...req.body, userId: req.user.id },
  });
  res.status(201).json(todo);
});

router.put('/:id', validateTodo, async (req, res) => {
  const { id } = req.params;
  const todo = await prisma.todo.update({
    where: { id: Number(id), userId: req.user.id },
    data: req.body,
  });
  res.json(todo);
});

router.delete('/:id', async (req, res) => {
  const { id } = req.params;
  await prisma.todo.delete({
    where: { id: Number(id), userId: req.user.id },
  });
  res.status(204).end();
});

export default router;
```

